def lettering(text, size, x, y, bold=False):
 font=TTFont('/usr/share/fonts/msttcore/georgiab.ttf' if bold else '/usr/share/fonts/msttcore/georgia.ttf'); glyphs=font.getGlyphSet(); cmap=font.getBestCmap();scale=size/font['head'].unitsPerEm;paths=[]
 for c in text:
  n=cmap.get(ord(c),'space');pen=SVGPathPen(glyphs);glyphs[n].draw(pen)
  if pen.getCommands():paths.append(f'<path d="{pen.getCommands()}" transform="translate({x:.3f},{y}) scale({scale},-{scale})"/>')
  x+=glyphs[n].width*scale
 return ''.join(paths)
