def pic(name,alt,cap,cls='hero-image'):
 return f'<figure class="{cls}"><img src="assets/{name}.webp" alt="{alt}" width="1500" height="1000" {"loading=\"lazy\"" if cls!="hero-image" else "fetchpriority=\"high\""}><figcaption class="caption">{cap}</figcaption></figure>'
def arrow():return '<span aria-hidden="true">↗</span>'
def btn(text,to,secondary=False):return f'<a class="button{" secondary" if secondary else ""}" href="{to}">{text} {arrow()}</a>'
def crumb(name):return f'<div class="wrap breadcrumb"><a href="index.html">Start</a> / {name}</div>'
def intro(kicker,title,lead):return f'<div class="wrap"><header class="page-intro"><p class="eyebrow">{kicker}</p><h1 tabindex="-1">{title}</h1><p class="lead">{lead}</p></header></div>'
products=[('Waldhonig','Kräftig und würzig für die Käsejause oder ein Butterbrot, das nach mehr schmecken darf',['250 g','500 g']),('Cremehonig','Fein gerührter, milder Honig für alle, die beim Frühstück gern dicker auftragen',['250 g','500 g']),('Honigwaben','Für alle, die’s gern am Stück haben, mit Honig direkt aus der Wabe zum Portionieren und Anrichten',['250 g','2 kg'])]
teasers=''.join(f'<article class="product-teaser"><div class="product-number">0{i+1}</div><h3>{n}</h3><p>{d}</p><span class="size">{" / ".join(sz)}</span><a class="text-link" href="honig.html#sorte-{i}">{n} ansehen {arrow()}</a></article>' for i,(n,d,sz) in enumerate(products))
pages={}
pages['index']=f'''<div class="wrap"><section class="hero"><div><p class="eyebrow">Imkerei · Krems & Umgebung</p><h1 tabindex="-1">Honig von hier.<br>Direkt von Thiemo.</h1><p class="lead">Waldhonig, Cremehonig und Honigwaben von der Imkerei Grassler.</p><div class="actions">{btn('Honig aussuchen','honig.html')}<a class="text-link" href="imkerei.html">Die Imkerei kennenlernen {arrow()}</a></div></div>{pic('honig','Honigglas mit Holzlöffel, von oben fotografiert.','Symbolfoto · Mike Jones / Pexels')}</section><div class="service-line"><span>Abholung nach Vereinbarung</span><span>Zustellung größerer Bestellungen im Raum Krems</span></div></div>
<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Das Sortiment</p><h2>Welcher darf’s sein?</h2></div><p>Was gerade da ist, hängt von der Ernte ab. Frag bitte vor der Abholung kurz nach.</p></div><div class="product-list">{teasers}</div></div></section>
<section class="section tinted"><div class="wrap split"><div><p class="eyebrow">Die Imkerei</p><h2>Thiemo Grassler.<br>Und seine Bienen.</h2></div><div class="text"><p>Thiemo imkert, weil ihm die Arbeit mit Bienen Freude macht. Er betreut die Völker selbst und füllt den Honig für den direkten Verkauf ab.</p><p>Bestellungen und Abholung vereinbarst du direkt mit ihm.</p><a class="text-link" href="imkerei.html">Mehr über die Imkerei {arrow()}</a></div></div></section>
<section class="section"><div class="wrap split"><div class="text"><p class="eyebrow">Ab Hof</p><h2>Ein Glas mitnehmen.<br>Oder ein paar mehr.</h2><p>Du möchtest Honig abholen? Gib die Sorte, Größe und Menge an. Thiemo klärt mit dir, was verfügbar ist und wann du vorbeikommen kannst.</p><p>Bei größeren Bestellungen ist eine Zustellung in Krems und der näheren Umgebung möglich.</p><div class="actions">{btn('Abholung anfragen','kontakt.html')}</div></div>{pic('wabe','Honig tropft aus einer geöffneten Wabe.','Symbolfoto · Archana GS / Pexels','large-figure')}</div></section>
<div class="wrap call-strip"><div><p class="eyebrow">Für Gastronomie</p><h2>Honig für euren Betrieb.</h2><p>Menge, Gebinde und Lieferung besprechen wir vorab.</p></div>{btn('Für Gastronomie','gastronomie.html',True)}</div>'''
details=[]
for i,(n,d,sz) in enumerate(products):
 sizes=''.join(f'<label><input type="radio" name="size-{i}" value="{z}" {"checked" if j==0 else ""}><span>{z}</span></label>' for j,z in enumerate(sz))
 details.append(f'<article class="product-detail" id="sorte-{i}"><div class="product-number">0{i+1}</div><div><h2>{n}</h2><p>{d}</p></div><div class="choice-box" data-product="{n}"><fieldset><legend>Glasgröße wählen</legend><div class="sizes">{sizes}</div></fieldset><a class="button product-request" href="kontakt.html?produkt={n}&groesse=250%20g">{n} anfragen {arrow()}</a><small>Preis und Verfügbarkeit auf Anfrage.</small></div></article>'.replace('<legend>Glasgröße wählen</legend>','<legend>Größe wählen</legend>' if i==2 else '<legend>Glasgröße wählen</legend>'))
pages['honig']=crumb('Honig & Waben')+intro('Honig & Waben','Drei Sorten.<br>Du hast die Wahl.','Waldhonig und Cremehonig im Glas, Honigwaben zum Portionieren. Hier findest du die Größen für deine Anfrage.')+f'<div class="wrap">{"".join(details)}<p class="note">Die Verfügbarkeit richtet sich nach Ernte und Jahreszeit. Eine Anfrage ist noch keine Bestellung. Preis und Übergabe werden vorab vereinbart.</p></div><section class="section"><div class="wrap split"><div><p class="eyebrow">Direkt von der Imkerei</p><h2>Vorbeikommen?<br>Bitte kurz absprechen.</h2></div><div class="text"><p>Abholung ist nach Vereinbarung möglich. Für größere Bestellungen im Raum Krems kann eine Zustellung vereinbart werden.</p><a class="text-link" href="kontakt.html">Abholung anfragen {arrow()}</a></div></div></section>'
pages['imkerei']=crumb('Die Imkerei')+intro('Die Imkerei','Hinter dem Honig<br>steht Thiemo.','Thiemo Grassler beschäftigt sich schon länger mit Bienen. Aus dem Interesse wurde eine eigene kleine Imkerei.')+f'''<section class="section tinted"><div class="wrap split"><div class="text"><p class="eyebrow">Krems & Umgebung</p><h2>Von den Bienen<br>bis ins Glas.</h2><p>Thiemo betreut die Völker selbst. Den geernteten Honig füllt er für den direkten Verkauf ab.</p><p>Im Sortiment sind Waldhonig, Cremehonig und Honigwaben. Wie viel verfügbar ist, hängt von der jeweiligen Ernte ab.</p><p>Wenn du etwas mitnehmen möchtest, vereinbarst du die Abholung direkt mit Thiemo.</p><div class="actions">{btn('Zum Sortiment','honig.html')}</div></div><aside class="region-panel"><svg viewBox="0 0 120 150" aria-hidden="true">{bee}</svg><p class="big">Krems<br>& Umgebung.</p><p>Hier wird der Honig geerntet, abgefüllt und direkt verkauft.</p><p class="caption">Die genaue Abholadresse erhältst du nach Vereinbarung.</p></aside></div></section><section class="section"><div class="wrap split"><div><p class="eyebrow">Persönlich vereinbart</p><h2>Du fragst.<br>Thiemo meldet sich.</h2></div><div class="text"><p>Sorte, Größe und Menge reichen für eine erste Anfrage. Verfügbarkeit und Übergabe klärt ihr dann direkt.</p><a class="text-link" href="kontakt.html">Anfrage vorbereiten {arrow()}</a></div></div></section>'''
pages['gastronomie']=crumb('Gastronomie')+intro('Für Gastronomie','Für euren<br>Frühstückstisch.','Oder für die Küche. Waldhonig, Cremehonig und Honigwaben könnt ihr direkt bei Thiemo anfragen.')+f'''<section class="section tinted"><div class="wrap split">{pic('wabe','Eine geöffnete Honigwabe mit einem Tropfen Honig.','Symbolfoto · Archana GS / Pexels','large-figure')}<div class="text"><p class="eyebrow">Mengen nach Absprache</p><h2>Was braucht<br>euer Betrieb?</h2><p>Waldhonig und Cremehonig gibt es in 250-g- und 500-g-Gläsern. Honigwaben sind mit 250 g und als 2-kg-Einheit vorgesehen, etwa fürs Frühstücksbuffet oder zur Käseplatte.</p><p>Gebt uns Sorte, Menge und Lieferort an. Preis und Termin werden vorab vereinbart.</p><dl class="facts"><div><dt>Gebiet</dt><dd>Krems & nähere Umgebung</dd></div><div><dt>Zustellung</dt><dd>Bei größeren Bestellungen</dd></div><div><dt>Konditionen</dt><dd>Nach Menge & Verfügbarkeit</dd></div><div><dt>Abholung</dt><dd>Nach Vereinbarung</dd></div></dl></div></div></section><section class="section"><div class="wrap call-strip" style="margin-bottom:0"><div><h2>Erzählt uns, was ihr vorhabt.</h2><p>Für eine erste Anfrage braucht es keine fertige Bestellliste.</p></div>{btn('Für den Betrieb anfragen','kontakt.html?produkt=Gastronomie-Anfrage')}</div></section>'''
pages['kontakt']=crumb('Kontakt & Anfrage')+intro('Kontakt & Anfrage','Welchen Honig<br>möchtest du?','Nenn uns die Sorte, Größe und Menge. Verfügbarkeit, Preis und Übergabe werden persönlich vereinbart.')+'''<div class="wrap contact-grid"><div><form id="request-form"><div class="form-grid"><div class="field"><label for="name">Dein Name *</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="reply">E-Mail oder Telefonnummer *</label><input id="reply" name="reply" required maxlength="160" aria-describedby="reply-help"><span class="help" id="reply-help">Damit Thiemo dir antworten kann.</span></div><div class="field"><label for="product">Produkt</label><select id="product" name="product"><option value="">Bitte auswählen</option><option>Waldhonig</option><option>Cremehonig</option><option>Honigwaben</option><option>Mehrere Produkte</option><option>Gastronomie-Anfrage</option></select></div><div class="field"><label for="size">Größe</label><select id="size" name="size"><option value="">Noch offen</option><option>250 g</option><option>500 g</option><option>2 kg</option></select></div><div class="field full"><label for="quantity">Gewünschte Menge</label><input id="quantity" name="quantity" placeholder="Zum Beispiel: 4 Gläser" maxlength="160"></div><div class="field full"><label for="message">Was möchtest du uns noch sagen?</label><textarea id="message" name="message" maxlength="3000" placeholder="Gewünschter Abholtermin oder Lieferort …"></textarea></div></div><div class="form-footer"><noscript><p>Die Anfrageaufbereitung benötigt JavaScript. Hier wird nichts versendet.</p></noscript><button type="submit" class="button" disabled>Anfragetext vorbereiten <span aria-hidden="true">↗</span></button><p>Vorschau: Deine Angaben bleiben in diesem Browser. Es wird nichts versendet oder gespeichert. * Pflichtfeld</p></div></form><section class="draft" id="draft" hidden aria-labelledby="draft-heading"><h2 id="draft-heading" tabindex="-1">Dein Anfragetext ist vorbereitet.</h2><p>Er wurde <strong>nicht versendet</strong>. Du kannst ihn kopieren oder als Textdatei speichern.</p><textarea id="draft-text" aria-label="Vorbereiteter Anfragetext" readonly></textarea><div class="actions"><button class="button" id="copy" type="button">Text kopieren</button><button class="button secondary" id="save" type="button">Als Textdatei speichern</button></div><p id="copy-status" class="status-text" role="status" aria-live="polite"></p></section></div><aside class="contact-aside"><p class="eyebrow">Direkt bei Thiemo</p><h2>Imkerei Grassler</h2><p>Thiemo Grassler<br>Krems und Umgebung</p><p>Abholung nach Vereinbarung.<br>Zustellung größerer Bestellungen im Raum Krems.</p><p class="help">Telefon, E-Mail und Anschrift sind noch nicht freigegeben. In dieser Vorschau kannst du deshalb nur einen Anfragetext vorbereiten.</p><a class="text-link" href="freigabe.html">Was vor dem Start noch fehlt ↗</a></aside></div>'''
pages['freigabe']=crumb('Freigabestand')+intro('Noch nicht veröffentlicht','Gestaltet.<br>Noch nicht freigegeben.','Diese Website ist eine lokal nutzbare Ausarbeitung. Sie nimmt keine Bestellungen entgegen und versendet keine Nachrichten.')+'''<div class="wrap"><div class="narrow"><h2>Vor der Veröffentlichung fehlen</h2><ul><li>Bestätigung der Betriebsangaben, Produkte, Größen und Liefermöglichkeiten durch Thiemo.</li><li>Vollständiger Betreibername, ladungsfähige Anschrift, Telefon und E-Mail.</li><li>Produktpreise und aktuelle Verfügbarkeit.</li><li>Domain und Hostingziel sowie ein geprüfter Versandweg für Kontaktanfragen.</li><li>Vollständiges Impressum und Datenschutzhinweise passend zum tatsächlichen Betrieb.</li><li>Freigabe der Symbolfotos oder Ersatz durch eigene Betriebs- und Produktfotos.</li><li>Ausdrückliche Freigabe zur Veröffentlichung.</li></ul><h2>Was bereits funktioniert</h2><p>Navigation, mobile Ansicht, Größenauswahl mit Übernahme ins Anfrageformular und das Vorbereiten, Kopieren und Speichern einer Anfrage als Textdatei.</p><h2>Was diese Website nicht ist</h2><p>Kein Onlineshop und kein Zahlungsportal. Eine Verfügbarkeit oder ein Liefertermin wird nicht automatisch zugesagt.</p></div></div>'''
pages['impressum']=crumb('Impressum')+intro('Entwurf · nicht zur Veröffentlichung','Impressum','Die Betreiberangaben wurden noch nicht übermittelt. Dieses Blatt ersetzt kein vollständiges Impressum.')+'''<div class="wrap"><div class="narrow"><h2>Noch zu ergänzen und zu prüfen</h2><ul><li>Vollständiger Name bzw. Firmenwortlaut und Rechtsform, soweit zutreffend.</li><li>Ladungsfähige Anschrift und direkte Kontaktmöglichkeiten.</li><li>Weitere gesetzlich erforderliche Angaben entsprechend der tatsächlichen Tätigkeit.</li></ul><p>Die Website darf mit diesem unvollständigen Stand nicht veröffentlicht werden.</p><h2>Bildnachweise für diesen Entwurf</h2><p>Honigglas: <a href="https://www.pexels.com/photo/close-up-photo-of-honey-on-a-jar-8805026/" target="_blank" rel="noopener noreferrer">Mike Jones / Pexels</a>.<br>Honigwabe: <a href="https://www.pexels.com/photo/close-up-photo-of-honey-comb-4111270/" target="_blank" rel="noopener noreferrer">Archana GS / Pexels</a>.</p><p>Beides sind Symbolfotos. Sie zeigen weder Produkte noch Bienenstände der Imkerei Grassler. Verwendung nach der <a href="https://www.pexels.com/license/" target="_blank" rel="noopener noreferrer">Pexels-Lizenz</a>. Keine KI-generierten Fotos.</p></div></div>'''
pages['datenschutz']=crumb('Datenschutz')+intro('Entwurf · nicht zur Veröffentlichung','Datenschutz','Für den tatsächlichen Websitebetrieb fehlen noch die Angaben zum Betreiber, Hosting und Anfrageversand.')+'''<div class="wrap"><div class="narrow"><h2>So arbeitet die lokale Vorschau</h2><p>Die Website setzt selbst keine Cookies, lädt keine externen Schriftdateien und enthält weder Analyse- noch Werbedienste. Die Bilder sind im Paket enthalten.</p><p>Das Formular bereitet ausschließlich einen Text im Browser vor. Seine Inhalte werden nicht an einen Server übermittelt und nicht in Local Storage oder Cookies gespeichert. Kopieren und Herunterladen erfolgen nur auf deinen Klick.</p><p>Externe Bildnachweise werden nur geöffnet, wenn du den jeweiligen Link anklickst. Bei Betrachtung über Notion oder einen anderen Hostingdienst gelten zusätzlich dessen eigene technische Abläufe.</p><h2>Für die Live-Version zu erstellen</h2><p>Datenschutzhinweise mit tatsächlichem Verantwortlichen, Verarbeitungszwecken, Rechtsgrundlagen, Empfängern, Speicherdauer, Betroffenenrechten und Informationen zum Hosting sowie Kontaktweg. Die Angaben sind vor dem Start zu prüfen.</p><p>Diese Vorschau ist keine fertige Datenschutzerklärung.</p></div></div>'''

# Revision 2: Austrian marketing voice, with facts preserved.
copy_revisions={'Honig von hier.<br>Direkt von Thiemo.': 'Ein bisserl Krems<br>fürs Butterbrot', 'Waldhonig, Cremehonig und Honigwaben von der Imkerei Grassler.': 'Waldhonig, Cremehonig und Honigwaben von Thiemo Grassler, für die Jause daheim und alle, die ihr Butterbrot gern ein bisserl ernster nehmen', 'Welcher darf’s sein?': 'Darf’s ein bisserl mehr sein?', 'Was gerade da ist, hängt von der Ernte ab. Frag bitte vor der Abholung kurz nach.': 'Was gerade ins Glas kommt, bestimmt die Ernte, deshalb am besten vor der Abholung kurz nachfragen', 'Thiemo Grassler.<br>Und seine Bienen.': 'Der Thiemo<br>hinterm Honig', 'Thiemo imkert, weil ihm die Arbeit mit Bienen Freude macht. Er betreut die Völker selbst und füllt den Honig für den direkten Verkauf ab.': 'Weil ihm die Arbeit mit Bienen Freude macht, kümmert sich Thiemo selbst um seine Völker und füllt den Honig für den direkten Verkauf ab.', 'Bestellungen und Abholung vereinbarst du direkt mit ihm.': 'Deinen Honig bekommst du nach Vereinbarung direkt bei ihm, ohne Umweg übers Supermarktregal.', 'Ein Glas mitnehmen.<br>Oder ein paar mehr.': 'Eins für daheim,<br>eins zum Mitbringen', 'Du möchtest Honig abholen? Gib die Sorte, Größe und Menge an. Thiemo klärt mit dir, was verfügbar ist und wann du vorbeikommen kannst.': 'Wenn du weißt, welcher Honig es werden soll, macht ihr Menge und Abholtermin direkt aus, damit du nicht auf gut Glück vor der Tür stehst.', 'Bei größeren Bestellungen ist eine Zustellung in Krems und der näheren Umgebung möglich.': 'Und wenn’s ein bisserl mehr wird, ist im Raum Krems nach Absprache auch eine Zustellung möglich.', 'Honig für euren Betrieb.': 'Ein bisserl Krems<br>für eure Gäste', 'Menge, Gebinde und Lieferung besprechen wir vorab.': 'Für Frühstücksbuffet und Küche gibt’s die passenden Mengen nach Absprache', 'Drei Sorten.<br>Du hast die Wahl.': 'Die Qual<br>der Honigwahl', 'Waldhonig und Cremehonig im Glas, Honigwaben zum Portionieren. Hier findest du die Größen für deine Anfrage.': 'Ob auf dem Butterbrot, bei der Käsejause oder gleich aus der Wabe, hier suchst du dir deinen Honig und die passende Größe aus', 'Vorbeikommen?<br>Bitte kurz absprechen.': 'Auf einen Sprung<br>zum Honig', 'Abholung ist nach Vereinbarung möglich. Für größere Bestellungen im Raum Krems kann eine Zustellung vereinbart werden.': 'Damit der Honig auch da ist, wenn du kommst, machen wir die Abholung vorher aus; bei größeren Mengen ist im Raum Krems auch eine Zustellung möglich.', 'Hinter dem Honig<br>steht Thiemo.': 'Kein Honig<br>von irgendwem', 'Thiemo Grassler beschäftigt sich schon länger mit Bienen. Aus dem Interesse wurde eine eigene kleine Imkerei.': 'Aus Thiemos Interesse an Bienen ist eine eigene kleine Imkerei geworden, deren Honig du direkt bei ihm bekommst', 'Von den Bienen<br>bis ins Glas.': 'Selber imkern,<br>persönlich ausmachen', 'Thiemo betreut die Völker selbst. Den geernteten Honig füllt er für den direkten Verkauf ab.': 'Um seine Völker und das Abfüllen kümmert sich Thiemo selbst, deine Bestellung und die Abholung macht ihr persönlich aus.', 'Im Sortiment sind Waldhonig, Cremehonig und Honigwaben. Wie viel verfügbar ist, hängt von der jeweiligen Ernte ab.': 'Waldhonig, Cremehonig oder Honigwaben kannst du dir aussuchen, wie viel davon da ist, hängt allerdings von der Ernte ab.', 'Wenn du etwas mitnehmen möchtest, vereinbarst du die Abholung direkt mit Thiemo.': 'Ein bisserl Geduld mit der Natur gehört also dazu, den Rest besprichst du am besten mit Thiemo.', 'Du fragst.<br>Thiemo meldet sich.': 'Red ma<br>über Honig', 'Sorte, Größe und Menge reichen für eine erste Anfrage. Verfügbarkeit und Übergabe klärt ihr dann direkt.': 'Sag Thiemo, welcher Honig es werden soll und wie viel du brauchst, dann klärt ihr, was gerade da ist und wann du vorbeikommen kannst.', 'Für euren<br>Frühstückstisch.': 'Ein guter Grund<br>für noch ein Semmerl', 'Oder für die Küche. Waldhonig, Cremehonig und Honigwaben könnt ihr direkt bei Thiemo anfragen.': 'Vom Frühstücksbuffet bis zur Käsejause gibt’s Waldhonig, Cremehonig und Honigwaben direkt von Thiemo aus Krems und Umgebung', 'Was braucht<br>euer Betrieb?': 'Für ein Glas<br>oder die ganze Frühstücksrunde', 'Gebt uns Sorte, Menge und Lieferort an. Preis und Termin werden vorab vereinbart.': 'Schreibt uns, welchen Honig ihr braucht, wie viel davon und wohin er soll, damit wir Preis und Termin mit euch abstimmen können.', 'Erzählt uns, was ihr vorhabt.': 'Was kommt bei euch auf den Tisch?', 'Für eine erste Anfrage braucht es keine fertige Bestellliste.': 'Ein paar Angaben reichen fürs Erste, die Einzelheiten machen wir persönlich aus', 'Welchen Honig<br>möchtest du?': 'Was darf’s<br>für dich sein?', 'Nenn uns die Sorte, Größe und Menge. Verfügbarkeit, Preis und Übergabe werden persönlich vereinbart.': 'Verrat uns, welcher Honig es werden soll und wie viel du brauchst, dann werden Verfügbarkeit, Preis und Übergabe persönlich vereinbart'}
for route in ["index","honig","imkerei","gastronomie","kontakt"]:
 for before,after in copy_revisions.items(): pages[route]=pages[route].replace(before,after)

nav=[('honig','Honig & Waben'),('imkerei','Die Imkerei'),('gastronomie','Gastronomie'),('kontakt','Anfragen')]
titles={'index':'Honig aus Krems & Umgebung','honig':'Honig & Waben','imkerei':'Die Imkerei','gastronomie':'Für Gastronomie','kontakt':'Kontakt & Anfrage','impressum':'Impressum · Entwurf','datenschutz':'Datenschutz · Entwurf','freigabe':'Freigabestand'}
header='''<a class="skip" href="#main">Zum Inhalt</a><div class="preview-bar">Website-Entwurf · Noch nicht veröffentlicht · <a href="freigabe.html">Freigabestand ansehen</a></div><div class="wrap"><header class="header"><a class="brand" href="index.html" aria-label="Imkerei Grassler – Startseite"><picture><source srcset="assets/logo-kurz-dark.svg" media="(prefers-color-scheme: dark)"><img src="assets/logo-kurz.svg" width="540" height="156" alt="Imkerei Grassler, Krems und Umgebung"></picture></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">Menü <span aria-hidden="true">＋</span></button><nav class="nav" id="navigation" aria-label="Hauptnavigation">'''+''.join(f'<a href="{r}.html" data-nav="{r}" {"class=\"contact-link\"" if r=="kontakt" else ""}>{n}</a>' for r,n in nav)+'''</nav></header></div>'''
footer='''<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand"><a class="brand" href="index.html"><img src="assets/logo-kurz-dark.svg" alt="Imkerei Grassler" width="540" height="156"></a><p>Honig von Thiemo Grassler.<br>Krems und Umgebung.<br>Abholung nach Vereinbarung.</p></div><div><h2>Die Imkerei</h2><a href="honig.html">Honig & Waben</a><a href="imkerei.html">Über Thiemo</a><a href="gastronomie.html">Für Gastronomie</a><a href="kontakt.html">Kontakt & Anfrage</a></div><div><h2>Gut zu wissen</h2><a href="impressum.html">Impressum · Entwurf</a><a href="datenschutz.html">Datenschutz · Entwurf</a><a href="freigabe.html">Freigabestand</a></div></div><div class="footer-bottom"><span>© Imkerei Grassler · Gestaltungsvorschau 2026</span><span>Symbolfotos: Mike Jones & Archana GS / Pexels</span></div></div></footer>'''
js=r'''
document.documentElement.classList.add('js');
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);toggle.innerHTML=open?'Menü <span aria-hidden="true">−</span>':'Menü <span aria-hidden="true">＋</span>';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){toggle.click();toggle.focus();}});
const preview=document.body.dataset.preview==='true';
function params(){return new URLSearchParams(preview?location.hash.split('?')[1]?.split('#')[0]:location.search);}
function init(){
 const route=document.querySelector('main').dataset.route;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.querySelectorAll('.choice-box').forEach(box=>{const update=()=>{const size=box.querySelector('input:checked').value;box.querySelector('a').href=(preview?'#/kontakt?':'kontakt.html?')+new URLSearchParams({produkt:box.dataset.product,groesse:size});};box.addEventListener('change',update);update();});
 const form=document.querySelector('#request-form');if(!form)return;
 form.querySelector('button[type=submit]').disabled=false;const p=params(),prod=document.querySelector('#product'),size=document.querySelector('#size');
 if([...prod.options].some(o=>o.value===p.get('produkt')))prod.value=p.get('produkt');
 function sizes(){let allowed=prod.value==='Honigwaben'?['250 g','2 kg']:['Waldhonig','Cremehonig'].includes(prod.value)?['250 g','500 g']:['250 g','500 g','2 kg'];[...size.options].forEach(o=>o.disabled=!!o.value&&!allowed.includes(o.value));if(size.selectedOptions[0]?.disabled)size.value='';}sizes();
 if([...size.options].some(o=>o.value===p.get('groesse')&&!o.disabled))size.value=p.get('groesse');prod.addEventListener('change',sizes);
 const reply=document.querySelector('#reply');reply.addEventListener('input',()=>reply.setCustomValidity(''));
 form.addEventListener('submit',e=>{e.preventDefault();const nameField=document.querySelector('#name');if(!nameField.value.trim()){nameField.setCustomValidity('Bitte deinen Namen eintragen.');nameField.reportValidity();nameField.addEventListener('input',()=>nameField.setCustomValidity(''),{once:true});return;}const v=reply.value.trim();const valid=v.includes('@')?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v):/^[+\d\s()/.-]+$/.test(v)&&v.replace(/\D/g,'').length>=6;if(!valid){reply.setCustomValidity('Bitte eine gültige E-Mail-Adresse oder Telefonnummer eintragen.');reply.reportValidity();return;}const f=new FormData(form);const text=`Hallo Thiemo,\n\nich möchte folgenden Honig anfragen:\n\nProdukt: ${f.get('product')||'noch offen'}\nGröße: ${f.get('size')||'noch offen'}\nMenge: ${String(f.get('quantity')).trim()||'noch offen'}\n\n${String(f.get('message')).trim()}\n\nBitte gib mir Bescheid, was verfügbar ist, was es kostet und wann eine Übergabe möglich wäre.\n\n${String(f.get('name')).trim()}\nRückmeldung an: ${v}`;document.querySelector('#draft-text').value=text.replace(/\n{3,}/g,'\n\n');document.querySelector('#draft').hidden=false;document.querySelector('#draft-heading').focus();});
 document.querySelector('#copy').onclick=async()=>{const el=document.querySelector('#draft-text'),s=document.querySelector('#copy-status');try{if(!navigator.clipboard)throw new Error();await navigator.clipboard.writeText(el.value);s.textContent='Kopiert. Die Anfrage wurde nicht versendet.';}catch{el.focus();el.select();s.textContent='Bitte den markierten Text mit Strg+C bzw. ⌘C kopieren. Die Anfrage wurde nicht versendet.';}};
 document.querySelector('#save').onclick=()=>{const u=URL.createObjectURL(new Blob([document.querySelector('#draft-text').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='Anfrage-Imkerei-Grassler.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);document.querySelector('#copy-status').textContent='Textdatei vorbereitet. Die Anfrage wurde nicht versendet.';};
}
if(preview){const templates=JSON.parse(document.querySelector('#page-data').textContent);const titles=JSON.parse(document.querySelector('#title-data').textContent);function route(first=false){const raw=location.hash.slice(2)||document.body.dataset.initial;const name=raw.split(/[?#]/)[0];const r=templates[name]?name:'index';const main=document.querySelector('main');main.innerHTML=templates[r];main.dataset.route=r;document.title=titles[r]+' | Imkerei Grassler';nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.innerHTML='Menü <span aria-hidden="true">＋</span>';init();const anchor=raw.includes('#')?raw.split('#')[1]:null;if(anchor)document.getElementById(anchor)?.scrollIntoView();else{window.scrollTo(0,0);if(!first)main.querySelector('h1')?.focus({preventScroll:true});}}window.addEventListener('hashchange',()=>route());route(true);}else init();
'''
(AS/'site.js').write_text(js)
def convert_links(s):
 return re.sub(r'href="(index|honig|imkerei|gastronomie|kontakt|impressum|datenschutz|freigabe)\.html([^" ]*)"',lambda m:f'href="#/{m[1]}{m[2]}"',s)
def inline_assets(s):
 for p in AS.iterdir():
  if p.suffix in ['.svg','.webp','.woff']:
   mime={'.svg':'image/svg+xml','.webp':'image/webp','.woff':'font/woff'}[p.suffix];s=s.replace('assets/'+p.name,'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode())
 return s
meta='<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f6eccb">'
for route in pages:
 htmltext=f'<!doctype html><html lang="de-AT"><head>{meta}<title>{titles[route]} | Imkerei Grassler</title><meta name="description" content="Waldhonig, Cremehonig und Honigwaben von Thiemo Grassler. Krems und Umgebung. Abholung nach Vereinbarung."><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script></head><body>{header}<main id="main" data-route="{route}">{pages[route]}</main>{footer}</body></html>'
 (SITE/f'{route}.html').write_text(htmltext)
 previewpages={r:convert_links(c) for r,c in pages.items()}
 # A single, self-contained site: works from attachment, offline, without server or CDN.
 previewtext=f'<!doctype html><html lang="de-AT"><head>{meta}<title>{titles[route]} | Imkerei Grassler</title><link rel="icon" href="assets/favicon.svg"><style>{css.replace("url(young-serif.woff)","url(assets/young-serif.woff)")}</style></head><body data-preview="true" data-initial="{route}">{convert_links(header)}<main id="main" data-route="{route}">{previewpages[route]}</main>{convert_links(footer)}<script type="application/json" id="page-data">{json.dumps(previewpages,ensure_ascii=False).replace("</", "<\\/")}</script><script type="application/json" id="title-data">{json.dumps(titles,ensure_ascii=False)}</script><script>{js}</script></body></html>'
 if route=='index':(ROOT/'Grassler-Website.html').write_text(inline_assets(previewtext))
(SITE/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(SITE/'release-config.json').write_text(json.dumps({'releaseApproved':False,'operatorName':None,'address':None,'email':None,'phone':None,'domain':None,'pricesConfirmed':False,'businessFactsConfirmed':False,'photosApproved':False,'imprintReviewed':False,'privacyReviewed':False,'contactDeliveryTested':False},indent=2))
(ROOT/'texte.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2))
print('Built',len(pages),'static routes and one standalone preview.',(ROOT/'Grassler-Website.html').stat().st_size,'bytes')
